{
  "IP": "neorv32_debug_auth",
  "Conceptual Assets": [
    {
      "Concept ID": "C1",
      "Concept Name": "Debug authentication state",
      "Unit": "neorv32_debug_auth",
      "Information": "The current debug authorization state, including the value written to establish or clear authentication, determines whether the debugger is considered authenticated. The unit depends on this state to report debug authorization through valid_o.",
      "Rubric": {
        "Confidentiality": "yes",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "The state is exposed directly through valid_o at line 66, allowing an integration observer to learn the authentication status. authenticated_q is changed from wdata_i(0) on a write at line 57, so unauthorized modification can change authorization. enable_i can clear authenticated_q at lines 54-55, and the cleared state is reflected on valid_o at line 66, so authentication can be disabled.",
      "Objectives At Risk": [
        "C",
        "I",
        "A"
      ],
      "Attack": "An attacker could observe valid_o, assert a write with a chosen wdata_i(0) value, or force enable_i low to disclose, alter, or disable the authentication state.",
      "Enters Through": [
        "wdata_i"
      ],
      "Leaves Through": [
        "valid_o"
      ],
      "Entry Lines": [
        57
      ],
      "Held Lines": [
        52,
        55,
        57
      ],
      "Exit Lines": [
        66
      ]
    },
    {
      "Concept ID": "C2",
      "Concept Name": "Authentication update request",
      "Unit": "neorv32_debug_auth",
      "Information": "The write request selects whether the incoming authentication value is accepted. The authentication function depends on this command to establish or change the debug authorization state.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "no",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "When we_i is not asserted, the process does not accept wdata_i to update authentication at line 56, so suppressing the request can prevent the authentication function from operating.",
      "Objectives At Risk": [
        "A"
      ],
      "Attack": "An attacker could suppress we_i so that authentication updates are never accepted and debug authorization remains unavailable.",
      "Enters Through": [
        "we_i"
      ],
      "Leaves Through": [],
      "Entry Lines": [
        56
      ],
      "Held Lines": [],
      "Exit Lines": []
    },
    {
      "Concept ID": "C3",
      "Concept Name": "Authentication enable control",
      "Unit": "neorv32_debug_auth",
      "Information": "The enable control determines whether authentication may be retained or updated. The unit uses it to permit debug authorization to remain active.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "no",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "enable_i clears the authentication state when low at lines 54-55, and authenticated_q drives valid_o at line 66, so the control can disable the debug authentication function.",
      "Objectives At Risk": [
        "A"
      ],
      "Attack": "An attacker could force enable_i low, clearing authenticated_q and disabling the reported debug authorization.",
      "Enters Through": [
        "enable_i"
      ],
      "Leaves Through": [],
      "Entry Lines": [
        54
      ],
      "Held Lines": [],
      "Exit Lines": []
    }
  ],
  "Not Kept": [
    {
      "Candidate Name": "Authentication write value",
      "Candidate Unit": "neorv32_debug_auth",
