      "Why Not Kept": ""
    },
    {
      "Candidate Name": "Read request",
      "Candidate Unit": "neorv32_debug_auth",
      "Merged Into": "",
      "Why Not Kept": "re_i is not read or used anywhere in the RTL, so it has no information flow or security mechanism in this unit (line 26)."
    },
    {
      "Candidate Name": "Readback data",
      "Candidate Unit": "neorv32_debug_auth",
      "Merged Into": "",
      "Why Not Kept": "rdata_o is assigned only constant zeroes at line 69 and therefore carries no runtime information requiring protection."
    },
    {
      "Candidate Name": "Busy status",
